; ============================================================================
; sideditor64.asm -- ENHANCED SIDPLAYER EDITOR 64 V1.0, the editor the
;   COMPUTE!'s Enhanced Sidplayer .mus format was written for, by Craig
;   Chamberlain -- the same author as the player (reference/sidobj64.asm).
; ============================================================================
;
; PROVENANCE
;   Compute's Gazette Sid Collection v1.47, disk 00_Commodore64, file
;   MusicSys.d64, program EDITOR2.64: 29,761 bytes, $0801-$7C3F, started by
;   CLR : SYS 2177 ($0881). The disk's "sid editor.64" is only a BASIC boot stub
;   (two REM lines, then SYS 2202 : LOAD "EDITOR2.64",8).
;
;   The program carries the title text "ENHANCED SIDPLAYER EDITOR 64 V1.0 BY
;   CRAIG CHAMBERLAIN", and "COPYRIGHT 1986 BY COMPUTE! PUBLICATIONS, INC." at
;   $0843.
;
;   Kept for study: it is the format's own editor, so the command set and the way
;   a tune is entered can be read here instead of guessed at. It is NOT built by
;   this repo, and it is not a reassemblable source:
;   there are no labels, code and data interleave, and the code is
;   position-dependent. As with the 1986 player, no explicit licence accompanies
;   it -- see NOTICE for how this repository treats COMPUTE! material. It is not
;   part of the published binaries (reference/ is not in that set).
;
;   Generated by tools/dis6502.py --asm; docs/development.md section 7 lists the
;   tools and how they are used.
;
; LANDMARKS (addresses verified by walking the code)
;   $0801  BASIC stub; the copyright string is at $0843.
;   $0881  entry: screen clear, VIC setup, NMI handler installed at $08C9-$08E2
;          ($0318/$0319 and $FFFA/$FFFB).
;
;   $1A40-$1C25  the IRQ handlers, one per editing mode. Fifteen sites of the form
;                LDA #lo / STA $0314 / LDA #hi / STA $0315
;          install them, and every one targets one of five addresses:
;              $1A40 x8   base handler: CIA1 $DC0D, UDTIM ($FFEA), SCNKEY ($FF9F)
;              $1AB9 x4   keyboard and timer: CIA1 matrix ($DC00/$DC01), Timer A
;                         ($DC04/$DC05), then UDTIM and SCNKEY
;              $1A50 x1   raster split: acks $D019, moves and recolours sprites
;                         ($D000/$D010/$D015/$D027,X), re-points $D018, sets $D012
;              $1B62 x1   raster split: changes $D016 either side of a raster wait
;              $1BCA x1   (CPX $D012) -- the same shape for both
;          The install sites, in address order:
;              $283E -> $1A50    $29E6 -> $1A40    $2A71 -> $1AB9
;              $2B39 -> $1A40    $3EF5 -> $1B62    $3F15 -> $1A40
;              $4042 -> $1BCA    $4062 -> $1A40    $4246 -> $1AB9
;              $4398 -> $1A40    $5DBB -> $1AB9    $5E5E -> $1AB9
;              $608A -> $1A40    $669D -> $1A40    $7320 -> $1A40
;          Reading the $D011 pair a split writes: the two values are $0B and $1B,
;          which differ in bit 4 -- $0B has the screen area blanked (it shows the
;          border colour) and $1B is the normal screen. Both set 25 rows (bit 3)
;          and leave YSCROLL at 3, so this is blanking, not a row-count change.
;
;   DISPLAY MEMORY. The configuration code at $699C indexes six 9-entry tables by
;   screen number -- border $0AE5, background $0AEE, VIC bank $0AF7, $D018 $0B00,
;   and two more at $0B09 and $0B12 -- so there are NINE screens, each with its
;   own bank, charset and screen matrix. Resolved from those tables: charsets at
;   $9000 and $9800 (VIC bank 2, $8000) and $F000 (bank 3, $C000); screen
;   matrices at $B000, $B400, $B800, $BC00, $C000, $C400 and $C800. All of it is
;   RAM the KERNAL would otherwise own, which is why the editor banks it out.
;
;   $1C6A  SID setup; $1D01 SID voice writes (reads $D41B/$D41C, oscillator 3).
;   $45F0  sprite positions ($D002-$D005, $D00A/$D00B) for the two sprites.
;   $69A0  per-screen VIC configuration: sprites ($D015/$D017/$D01D), border and
;          background, the VIC bank through CIA2 PA ($DD00, low bits from a table
;          at $0AF7), $D018 and $D010.
;   $6A32  raster and row helpers; its two $D011 values are written at $6A4E and
;          $6A5E.
;   $6F66  KERNAL GETIN for keystrokes -- the IRQ handlers do the scanning.
;   $728C  where the IRQ install ($7313-$7322) saves the old $0314/$0315.
;   $7341  SID init.
